-- +goose Up
-- owner: Content
CREATE TABLE content_achievement_catalogs(revision_id text PRIMARY KEY REFERENCES gxb_content_revisions(revision_id),payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'));
-- owner: Achievement
CREATE TABLE achievement_roots(player_id bigint PRIMARY KEY REFERENCES players(player_id),content_revision text NOT NULL REFERENCES gxb_content_revisions(revision_id),policy_id text NOT NULL CHECK(policy_id='C4B_MARRIED_POPULATION_TIER_FACTS_V1'),progress bigint NOT NULL CHECK(progress BETWEEN 0 AND 9007199254740991),complete_times jsonb NOT NULL CHECK(jsonb_typeof(complete_times)='array' AND jsonb_array_length(complete_times)=3),state_version bigint NOT NULL CHECK(state_version>0),created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL CHECK(updated_at>=created_at));
CREATE TABLE achievement_events(player_id bigint NOT NULL REFERENCES achievement_roots(player_id),event_key text NOT NULL CHECK(length(event_key)=64),fingerprint text NOT NULL CHECK(length(fingerprint)=64),source_operation uuid NOT NULL,partner_id bigint NOT NULL CHECK(partner_id>0),old_version bigint NOT NULL CHECK(old_version>0),new_version bigint NOT NULL CHECK(new_version=old_version+1),population bigint NOT NULL CHECK(population>0),content_revision text NOT NULL REFERENCES gxb_content_revisions(revision_id),decision_at timestamptz NOT NULL,PRIMARY KEY(player_id,event_key),UNIQUE(player_id,source_operation));
